   100→      } else if (fnItem.type === 'VFunction') {
   101→        this.genVFunction(fnItem as AST.VFunction);
   102→      } else if (fnItem.type === 'PyFunction') {
   103→        this.genPyFunction(fnItem as AST.PyFunction);
   104→      } else if (fnItem.type === 'StructDef') {
   105→        this.genVStructDef(fnItem as AST.StructDef);
   106→        // struct 정의는 항상 Python class도 함께 생성
   107→        this.genPyStructDef(fnItem as AST.StructDef);
   108→      } else if (fnItem.type === 'Return' || fnItem.type === 'Assign' || fnItem.type === 'ExprStatement' || fnItem.type === 'MatchStatement') {
   109→        // 탑레벨 문장은 V 모드(C)로 처리
   110→        this.genVStatement(fnItem as AST.Statement);
   111→      }
   112→    }
   113→
   114→    const c = this.cLines.join('\n');
   115→    const python = this.pyLines.join('\n');
   116→
   117→    // mixed: 두 언어 코드를 주석으로 구분해서 출력 (확인용)
   118→    const mixed =
   119→      c && python
   120→        ? `/* ===== V (C) ===== */\n${c}\n\n/* ===== Python ===== */\n# (Not valid C, just for reference)\n${python}`
   121→        : c || python;
   122→
   123→    return {
   124→      c,
   125→      python,
   126→      mixed,
   127→      linkFlags: Array.from(this.linkFlagsSet),
   128→      externLibs: this.externLibs,
   129→    };
   130→  }
   131→
   132→  /**
   133→   * 실행 가능한 프로그램 생성
   134→   * C에는 #include + main() 추가, Python에는 if __name__ 추가
   135→   */
   136→  generateProgram(program: AST.Program): CodegenResult {
   137→    const base = this.generate(program);
   138→
   139→    // fn main()이 이미 있으면 int main() 추가하지 않음
   140→    const hasMain = program.body.some(
   141→      (n: any) => n.type === 'VFunction' && n.name === 'main'
   142→    );
   143→
   144→    // Python 모듈 자동 초기화 코드 삽입 (fn main 앞에 __attribute__((constructor)) 사용)
   145→    const pyInits = Array.from(this.pyAliasMap.keys())
   146→      .map(alias => `    __fl_py_init_${alias}();`)
   147→      .join('\n');
   148→    const pyFinalize = this.pyAliasMap.size > 0 ? '\n    Py_Finalize();' : '';
   149→

