     1→/**
     2→ * FreeLang Nexus Phase N.4 테스트
     3→ * - break / continue
     4→ * - 배열 리터럴 선언 (타입 추론 + 명시적 타입)
     5→ * - stdlib 확대: abs, min, max, sqrt, pow, str_len, str_contains, str_eq
     6→ */
     7→
     8→import { NexusLexer } from '../src/nexus/lexer/nexus-lexer';
     9→import { NexusParser } from '../src/nexus/parser/nexus-parser';
    10→import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';
    11→
    12→function compile(code: string): string {
    13→  const lexer = new NexusLexer(code);
    14→  const tokens = lexer.tokenize();
    15→  const parser = new NexusParser(tokens);
    16→  const ast = parser.parse();
    17→  const codegen = new NexusCodegen();
    18→  return codegen.generate(ast).c;
    19→}
    20→
    21→// ─── break / continue ───────────────────────────────────────────────────────
    22→
    23→describe('Phase N.4 - break / continue', () => {
    24→  test('Test 1: while 루프 내 break 코드젠', () => {
    25→    const c = compile(`@mode(v)
    26→fn test() -> i64 {
    27→  let i = 0
    28→  while i < 10 {
    29→    if i == 5 {
    30→      break
    31→    }
    32→    i = i + 1
    33→  }
    34→  return i
    35→}`);
    36→    expect(c).toContain('break;');
    37→    expect(c).toContain('while (i < 10)');
    38→  });
    39→
    40→  test('Test 2: while 루프 내 continue 코드젠', () => {
    41→    const c = compile(`@mode(v)
    42→fn test() -> i64 {
    43→  let i = 0
    44→  while i < 10 {
    45→    i = i + 1
    46→    if i == 3 {
    47→      continue
    48→    }
    49→    println("hi")
    50→  }
    51→  return 0
    52→}`);
    53→    expect(c).toContain('continue;');
    54→  });
    55→
    56→  test('Test 3: for 루프 내 break 코드젠', () => {
    57→    const c = compile(`@mode(v)
    58→fn test() -> i64 {
    59→  for i in range(100) {
    60→    if i == 10 {
    61→      break
    62→    }
    63→  }
    64→  return 0
    65→}`);
    66→    expect(c).toContain('break;');
    67→    expect(c).toContain('for (long long i = 0; i < 100; i++)');
