// ─── 4. 로컬 변수 ─────────────────────────────────────────────────────────────

describe('WAT 코드 생성 - 로컬 변수', () => {
  test('Test 18: let 변수 → (local ...) 선언', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
