    return 1
  }
  return 0
}`);
    // 조건: x > 5 → local.get $x, i64.const 5, i64.gt_s
    expect(result).toContain('local.get $x');
    expect(result).toContain('i64.const 5');
    expect(result).toContain('i64.gt_s');
