// ─── 6. while 루프 ────────────────────────────────────────────────────────────

describe('WAT 코드 생성 - while 루프', () => {
  test('Test 26: while 루프 → block/loop 구조', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
