  }
  return i
}`);
    expect(result).toContain('(block');
    expect(result).toContain('(loop');
  });

  test('Test 27: while 루프 → br_if 탈출 조건', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  let i = 0
  while i < 10 {
    i = i + 1
  }
  return i
}`);
    expect(result).toContain('br_if');
    expect(result).toContain('i32.eqz');
  });

  test('Test 28: while 루프 → br (back-edge)', () => {
    const result = wat(`@mode(v)
fn test() -> i64 {
  let i = 0
  while i < 5 {
    i = i + 1
  }
  return i
}`);
